import math

from ratelimit.window import FixedWindow


def retry_after(window: FixedWindow, now: float) -> int:
    remaining = window.start + window.seconds - now
    return max(0, math.ceil(remaining))


def headers(window: FixedWindow, now: float) -> dict[str, str]:
    return {
        "X-RateLimit-Remaining": str(max(0, window.limit - window.count)),
        "Retry-After": str(retry_after(window, now)),
    }
